#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INF 1000000000

static int dp[305][2705];

static inline int min(int a, int b) {
    return a < b ? a : b;
}

int main(void) {
    int n, k;
    long long t_in;
    if (scanf("%d %d %lld", &n, &k, &t_in) != 3) return 0;

    int *p = (int *)malloc((n + 1) * sizeof(int));
    for (int i = 1; i <= n; i++) {
        scanf("%d", &p[i]);
    }

    int *a = (int *)malloc((k + 1) * sizeof(int));
    int friend_idx = 1;
    for (int i = 1; i <= n; i++) {
        int g;
        scanf("%d", &g);
        if (g == 1) {
            a[friend_idx++] = i;
        }
    }

    int max_swaps = n * (n - 1) / 2;
    int t = (t_in > max_swaps) ? max_swaps : (int)t_in;

    int max_v = 9 * k;

    for (int j = 0; j <= k; j++) {
        for (int v = 0; v <= max_v; v++) {
            dp[j][v] = INF;
        }
    }
    dp[0][0] = 0;

    for (int i = 1; i <= n; i++) {
        int pi = p[i];
        int j_max = (i < k) ? i : k;
        for (int j = j_max; j >= 1; j--) {
            int cost = abs(i - a[j]);
            int v_max = 9 * j;
            for (int v = v_max; v >= pi; v--) {
                if (dp[j - 1][v - pi] + cost < dp[j][v]) {
                    dp[j][v] = dp[j - 1][v - pi] + cost;
                }
            }
        }
    }

    int ans = 0;
    for (int v = max_v; v >= 0; v--) {
        if (dp[k][v] <= t) {
            ans = v;
            break;
        }
    }

    printf("%d\n", ans);

    free(p);
    free(a);
    return 0;
}
